#include <iostream>
#include <string>
#include <vector>
#include <queue>

struct TNode {
    int val;
    TNode* left;
    TNode* right;
    TNode(int v) : val(v), left(nullptr), right(nullptr) {}
};

static int parse_line(const std::string& line, int* out) {
    int cnt = 0;
    size_t i = 0;
    while (i < line.size()) {
        while (i < line.size() && (line[i] == ' ' || line[i] == '\t' || line[i] == '\r')) i++;
        if (i >= line.size()) break;
        int sign = 1;
        if (line[i] == '-') { sign = -1; i++; }
        long long v = 0;
        bool any = false;
        while (i < line.size() && line[i] >= '0' && line[i] <= '9') {
            v = v * 10 + (line[i] - '0');
            i++;
            any = true;
        }
        if (any) out[cnt++] = (int)(sign * v);
    }
    return cnt;
}

static int read_token_line(int* out) {
    std::string line;
    std::getline(std::cin, line);
    return parse_line(line, out);
}

static void skip_rest_of_line() {
    std::string line;
    std::getline(std::cin, line);
}

TNode* build_tree(int* vals, int nv) {
    if (nv <= 0 || vals[0] == -1) return nullptr;
    TNode* root = new TNode(vals[0]);
    static TNode* bq[20010];
    int head = 0, tail = 0;
    bq[tail++] = root;
    int i = 1;
    while (head < tail && i < nv) {
        TNode* cur = bq[head++];
        if (i < nv) {
            if (vals[i] != -1) {
                TNode* c = new TNode(vals[i]);
                cur->left = c;
                bq[tail++] = c;
            }
            i++;
        }
        if (i < nv) {
            if (vals[i] != -1) {
                TNode* c = new TNode(vals[i]);
                cur->right = c;
                bq[tail++] = c;
            }
            i++;
        }
    }
    return root;
}

void level_order(TNode* root, std::vector<int>& out) {
    if (!root) return;
    std::queue<TNode*> q;
    q.push(root);
    while (!q.empty()) {
        TNode* cur = q.front();
        q.pop();
        out.push_back(cur->val);
        if (cur->left) q.push(cur->left);
        if (cur->right) q.push(cur->right);
    }
}

int main() {
    long long declared;
    std::cin >> declared;
    skip_rest_of_line();
    static int vals[20005];
    int nv = read_token_line(vals);
    TNode* root = build_tree(vals, nv);
    std::vector<int> out;
    level_order(root, out);
    for (size_t i = 0; i < out.size(); i++) {
        if (i) std::cout << ' ';
        std::cout << out[i];
    }
    std::cout << std::endl;
    return 0;
}

